<script lang="ts">
 import {languageOverrides} from "./localization";
 import {printDocument} from "./print-dialog";
 import {openInterval} from "./report-interval";
 import type {Project} from './model';import {translator} from './i18n';import {monthNext} from './engine';import {exportText,exportBinary,exportPDF,native} from './storage';import {ReceiptText,Printer,Download,Settings2} from '@lucide/svelte';
 import {paymentMatrix,paymentMatrixHTML,paymentMatrixCSV,paymentMatrixXLSX,paymentMatrixDefaults} from './payment-matrix';import {emptyReportFilters,reportFilterData} from './report-filter-data';import {openReportSettings,type SortRule} from './report-settings';import ReportFilter from './ReportFilter.svelte';
 export let project:Project;export let initialAccountId="";export let initialPeriod=project.settings.period;
 let from=initialPeriod+'-01',to=new Date(Date.parse(monthNext(initialPeriod)+'-01T00:00:00Z')-86400000).toISOString().slice(0,10),options=paymentMatrixDefaults(),sort:SortRule[]=[],generated='',error='',ready=false,preview:HTMLIFrameElement,lastSignature='';
 options.filters=emptyReportFilters();if(initialAccountId)options.filters[0]={...options.filters[0],enabled:true,values:[initialAccountId]};
 $:t=translator(project.settings.language,$languageOverrides);$:filterData=reportFilterData(project);
 $:report=(()=>{try{return paymentMatrix(project,from,to,options);}catch{return null;}})();
 $:{const signature=JSON.stringify([from,to,options,project.settings.language]);if(signature!==lastSignature){generated='';ready=false;lastSignature=signature;}}
 function generate(){try{generated=paymentMatrixHTML(project,from,to,options);ready=false;error='';}catch(e){error=String(e);}}
 function configure(){openReportSettings({id:'payments',filters:options.filters,sort,labels:filterData.labels,items:filterData.items,columns:report?.headers||[],onapply:(filters,rules)=>{options={...options,filters,sort:rules};sort=rules;}});}
 async function download(format:'pdf'|'xlsx'|'csv'|'html'){try{const name=`OpenHaU-payments-${from}-${to}.${format}`;if(format==='pdf')await exportPDF(name,paymentMatrixHTML(project,from,to,options),true);else if(format==='xlsx')await exportBinary(name,paymentMatrixXLSX(project,from,to,options),'xlsx');else await exportText(name,format==='csv'?paymentMatrixCSV(project,from,to,options):paymentMatrixHTML(project,from,to,options),format);error='';}catch(e){error=String(e);}}
</script>
<div class="legacy-report">
 <div class="report-command-row"><button onclick={generate} disabled={!report}><ReceiptText size={16}/>{t('Сформировать','Generează')}</button><button onclick={configure}><Settings2 size={16}/>{t('Настройка…','Configurare…')}</button></div>
 <div class="report-period"><span>{t('Период с','Perioada de la')}</span><input type="date" aria-label={t('Период с','Perioada de la')} bind:value={from}/><span>{t('по','până la')}</span><input type="date" aria-label={t('Период по','Perioada până la')} bind:value={to}/><button class="icon-button" aria-label={t('Настройка интервала','Configurare interval')} onclick={()=>openInterval({id:"payments",current:project.settings.period,from,to,onapply:(start,end)=>{from=start;to=end;}})}>…</button></div>
 {#each [0,3,4] as index}<ReportFilter language={project.settings.language} label={filterData.labels[index]} items={filterData.items[index]} bind:filter={options.filters[index]}/>{/each}
 <div class="report-group-options"><div><label class="check-row"><input type="checkbox" bind:checked={options.expandAccounts}/>{t('Разворачивать по лицевым счетам','Detaliere pe conturi personale')}</label><label class="check-row"><input type="checkbox" bind:checked={options.showAddress} disabled={!options.expandAccounts}/>{t('Выводить колонку «Адрес»','Afișează coloana „Adresă”')}</label><label class="check-row"><input type="checkbox" bind:checked={options.groupServiceTypes}/>{t('Группировать по видам услуг','Grupează după tipuri de servicii')}</label></div><fieldset><legend>{t('Группировать по','Grupează după')}</legend><label><input type="radio" value="method" bind:group={options.grouping}/>{t('вариантам оплаты','modalități de plată')}</label><label><input type="radio" value="date" bind:group={options.grouping}/>{t('датам','date')}</label></fieldset></div>
 <div class="report-output-tools"><button disabled={!ready} onclick={()=>void printDocument(generated,true)}><Printer size={16}/>{t('Печать','Imprimare')}</button><button disabled={!native||!report} onclick={()=>download('pdf')}><Download size={16}/>{t('Сохранить PDF','Salvează PDF')}</button><button disabled={!report} onclick={()=>download('xlsx')}><Download size={16}/>Excel XLSX</button><button disabled={!report} onclick={()=>download('csv')}><Download size={16}/>CSV</button><button disabled={!report} onclick={()=>download('html')}><Download size={16}/>HTML</button></div>
 {#if error}<p class="alert error" role="alert">{error}</p>{/if}
 {#if generated}<iframe title={t('Предпросмотр отчёта по оплатам','Previzualizarea raportului de plăți')} bind:this={preview} srcdoc={generated} sandbox="allow-same-origin allow-modals" onload={()=>ready=true}></iframe>{:else if !report}<p role="alert">{t('Проверьте диапазон дат','Verificați intervalul de date')}</p>{:else}<div class="report-placeholder">{t('Укажите отбор и нажмите «Сформировать».','Selectați filtrele și apăsați „Generează”.')}</div>{/if}
</div>
<style>.legacy-report{display:flex;flex-direction:column;gap:6px;min-height:100%;padding:0 8px 8px;box-sizing:border-box}.report-command-row,.report-output-tools{display:flex;gap:3px;align-items:center;flex-wrap:wrap}.report-command-row button,.report-output-tools button{padding:8px 10px;display:flex;gap:7px;align-items:center;border:0;background:transparent;color:var(--text)}.report-command-row{border-bottom:1px solid var(--border);padding-bottom:4px}.report-period{display:flex;align-items:center;gap:10px;margin:6px 0}.report-period input{width:180px;padding:6px}.report-group-options{display:flex;gap:28px;padding:12px 0;border-top:1px solid var(--border)}.report-group-options>div{display:grid;gap:7px}fieldset{border:0;padding:0 16px}fieldset label{display:block;padding:4px 0}.report-output-tools{border-top:1px solid var(--border);border-bottom:1px solid var(--border)}iframe{width:100%;height:60vh;min-height:300px;flex:1;border:0;background:white}.report-placeholder{min-height:260px;background:var(--input);padding:20px;color:var(--muted)}</style>
